import { test, expect } from '@playwright/test';

test.describe('Item Detail View - Single Item View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/items');
  });

  test('should display item details when clicking on an item card', async ({ page }) => {
    // Verify item list is visible
    const itemCards = page.getByRole('region', { name: /item card/i });
    await expect(itemCards).toBeVisible();

    // Get the first item card and click it
    const firstItemCard = page.locator('[data-testid="item-card-1"]');
    await expect(firstItemCard).toBeVisible();
    await firstItemCard.click();

    // Verify item detail page is loaded
    await expect(page).toHaveURL(/.*\/items\/1/);

    // Verify item title is displayed
    const itemTitle = page.getByRole('heading', { name: /awesome gadget/i });
    await expect(itemTitle).toBeVisible();

    // Verify item description is displayed
    const itemDescription = page.getByText(/a revolutionary gadget for everyday use/i);
    await expect(itemDescription).toBeVisible();

    // Verify item price is displayed
    const itemPrice = page.getByText(/\$99.99/);
    await expect(itemPrice).toBeVisible();

    // Verify item image is displayed
    const itemImage = page.getByRole('img', { name: /awesome gadget/i });
    await expect(itemImage).toBeVisible();

    // Verify back button is available
    const backButton = page.getByRole('button', { name: /back to items/i });
    await expect(backButton).toBeVisible();
  });

  test('should handle item not found scenario when clicking on invalid item ID', async ({ page }) => {
    // Navigate to item list
    await page.goto('/items');

    // Click on a non-existent item ID
    const invalidItemLink = page.getByRole('link', { name: /item 999/i });
    await expect(invalidItemLink).toBeVisible();
    await invalidItemLink.click();

    // Verify 444 not found page is displayed
    await expect(page).toHaveURL(/.*\/items\/999/);
    const notFoundMessage = page.getByText(/item not found/i);
    await expect(notFoundMessage).toBeVisible();

    // Verify error state is displayed
    const errorContainer = page.locator('[data-testid="error-state"]');
    await expect(errorContainer).toBeVisible();

    // Verify back button is available
    const backButton = page.getByRole('button', { name: /back to items/i });
    await expect(backButton).toBeVisible();

    // Click back button to return to list
    await backButton.click();
    await expect(page).toHaveURL(/.*\/items/);
  });
});
